#include "postquantiquecoin/wallet/WalletEncryption.h"
#include "postquantiquecoin/crypto/Hashing.h"
#include "postquantiquecoin/crypto/SecureRandom.h"
#include "postquantiquecoin/wallet/WalletKdf.h"
#include "postquantiquecoin/wallet/WalletSecretBox.h"
#include <algorithm>
namespace pqc { WalletEncryptedBlob WalletEncryption::EncryptPayload(const std::vector<uint8_t>& plaintext,const std::string& password,uint32_t iterations){ WalletEncryptedBlob b; b.salt=SecureRandom::Bytes(32); b.nonce=SecureRandom::Bytes(12); auto key=WalletKdf::DeriveKey(password,b.salt,iterations,32); std::vector<uint8_t> aad{'P','Q','C','W','A','L','L','E','T','2'}; auto enc=WalletSecretBox::Encrypt(key,b.nonce,plaintext,aad); b.ciphertext=enc.ciphertext; b.authTag=enc.tag; std::vector<uint8_t> chk=b.salt; chk.insert(chk.end(),b.nonce.begin(),b.nonce.end()); chk.insert(chk.end(),b.ciphertext.begin(),b.ciphertext.end()); chk.insert(chk.end(),b.authTag.begin(),b.authTag.end()); b.checksum=Hashing::Sha3_256(chk); return b; } Result<std::vector<uint8_t>> WalletEncryption::DecryptPayload(const WalletEncryptedBlob& b,const std::string& password,uint32_t iterations){ std::vector<uint8_t> chk=b.salt; chk.insert(chk.end(),b.nonce.begin(),b.nonce.end()); chk.insert(chk.end(),b.ciphertext.begin(),b.ciphertext.end()); chk.insert(chk.end(),b.authTag.begin(),b.authTag.end()); auto c=Hashing::Sha3_256(chk); if(c!=b.checksum) return Result<std::vector<uint8_t>>::Err("wallet checksum mismatch"); auto key=WalletKdf::DeriveKey(password,b.salt,iterations,32); std::vector<uint8_t> aad{'P','Q','C','W','A','L','L','E','T','2'}; return WalletSecretBox::Decrypt(key,b.nonce,b.ciphertext,aad,b.authTag); } }
